using System.Diagnostics;
using System.Globalization;
using System.Text;

namespace CarsControl.Core.Storage;

/// <summary>
/// Reads a WizTree CSV export (verified against WizTree 4.33 on this PC):
///   line 1: "Generated by WizTree …" banner (free edition), then the header
///   File Name,Size,Allocated,Modified,Attributes,Files,Folders[,DRIVECAPACITY,FREESPACE,USEDSPACE,RESERVEDSPACE]
///   folder rows end in '\' and carry *recursive* Size and Files; the first row also carries drive totals.
/// WizTree reads the NTFS master file table directly (needs admin, done by the helper), which is why it
/// takes seconds even on the A: hard drive where a folder walk takes many minutes.
/// Totals use **Allocated** (space on disk), not Size: online-only iCloud files carry their full Size
/// with nothing allocated, and counting Size showed 1.3 TB on A:, a drive with 0.97 TB in use.
/// </summary>
public static class WizTreeImport
{
    public static readonly string ExePath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), @"WizTree\WizTree64.exe");

    public static bool IsInstalled => File.Exists(ExePath);

    // FILE_ATTRIBUTE_OFFLINE | FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS mark cloud placeholders. (0x40000 means
    // FILE_ATTRIBUTE_EA in the file table, set on ~120,000 real files on D:, so it isn't used here.)
    private const int OnlineOnlyAttributes = 0x1000 | 0x400000;

    public static ScanResult Parse(string csvPath, string rootPath, TimeSpan scanTime, IProgress<ScanProgress>? progress = null, CancellationToken ct = default)
    {
        using var reader = new StreamReader(csvPath, Encoding.UTF8, detectEncodingFromByteOrderMarks: true, bufferSize: 1 << 16);
        return Parse(reader, rootPath, scanTime, progress, ct);
    }

    public static ScanResult Parse(TextReader reader, string rootPath, TimeSpan scanTime, IProgress<ScanProgress>? progress = null, CancellationToken ct = default)
    {
        var sw = Stopwatch.StartNew();
        var nodes = new Dictionary<string, DirNode>(StringComparer.OrdinalIgnoreCase);
        var largest = new PriorityQueue<BigFile, long>();
        var old = new List<BigFile>();
        var oldCutoff = DateTime.Now - FolderScanner.OldAge;
        DirNode? root = null;
        long used = 0, rows = 0, onlineOnly = 0;

        string? line;
        while ((line = reader.ReadLine()) is not null && !line.StartsWith("File Name,", StringComparison.Ordinal)) { }
        if (line is null) throw new InvalidDataException("Not a WizTree export: header not found.");

        while ((line = reader.ReadLine()) is not null)
        {
            if (line.Length == 0) continue;
            var f = SplitCsv(line);
            if (f.Count < 7) continue;
            var path = f[0];
            long.TryParse(f[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out var size);
            long.TryParse(f[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out var allocated);

            if (path.EndsWith('\\'))
            {
                var node = GetOrCreate(path);
                node.TotalBytes = allocated;
                long.TryParse(f[5], NumberStyles.Integer, CultureInfo.InvariantCulture, out var files);
                node.TotalFiles = files;
                if (root is null)
                {
                    root = node;
                    if (f.Count >= 10) long.TryParse(f[9], NumberStyles.Integer, CultureInfo.InvariantCulture, out used);
                }
            }
            else
            {
                int.TryParse(f[4], NumberStyles.Integer, CultureInfo.InvariantCulture, out var attributes);
                if ((attributes & OnlineOnlyAttributes) != 0 && allocated < size) onlineOnly += size - allocated;
                if (allocated > 0) // 0: online-only, or small enough to live inside the file table
                {
                    var modified = DateTime.TryParseExact(f[3], "yyyy/MM/dd HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.AssumeLocal, out var m) ? m : DateTime.MinValue;
                    if (largest.Count < FolderScanner.LargestCount || allocated > largest.Peek().Bytes)
                    {
                        largest.Enqueue(new BigFile(path, allocated, modified), allocated);
                        if (largest.Count > FolderScanner.LargestCount) largest.Dequeue();
                    }
                    if (allocated >= FolderScanner.OldMinBytes && modified != DateTime.MinValue && modified < oldCutoff && old.Count < 5000)
                        old.Add(new BigFile(path, allocated, modified));
                }
            }

            if (++rows % 50_000 == 0)
            {
                ct.ThrowIfCancellationRequested();
                progress?.Report(new ScanProgress(rows, root?.TotalBytes ?? 0, path));
            }
        }

        root ??= new DirNode(rootPath, null);
        root.FinishFromTotals();
        return new ScanResult
        {
            Root = root,
            Largest = largest.UnorderedItems.Select(x => x.Element).OrderByDescending(x => x.Bytes).ToList(),
            OldLarge = old.OrderByDescending(x => x.Bytes).ToList(),
            Elapsed = scanTime + sw.Elapsed,
            When = DateTime.Now,
            DriveUsedBytes = used,
            Method = "Fast scan (MFT)",
            OnlineOnlyBytes = onlineOnly,
        };

        // Rows normally arrive parent-first; placeholders cover any that don't.
        DirNode GetOrCreate(string folderPath)
        {
            if (nodes.TryGetValue(folderPath, out var existing)) return existing;
            var trimmed = folderPath.TrimEnd('\\');
            var parentDir = Path.GetDirectoryName(trimmed);
            DirNode? parent = null;
            if (!string.IsNullOrEmpty(parentDir) && root is not null && folderPath.Length > root.FullPath.Length)
                parent = GetOrCreate(parentDir.EndsWith('\\') ? parentDir : parentDir + "\\");
            var name = parent is null ? (trimmed.Length == 2 ? trimmed + "\\" : trimmed) : Path.GetFileName(trimmed);
            var node = new DirNode(name, parent);
            parent?.Children.Add(node);
            nodes[folderPath] = node;
            return node;
        }
    }

    /// <summary>CSV split for WizTree rows: quoted first field (may contain commas and doubled quotes).</summary>
    internal static List<string> SplitCsv(string line)
    {
        var fields = new List<string>(12);
        var sb = new StringBuilder();
        var inQuotes = false;
        for (var i = 0; i < line.Length; i++)
        {
            var c = line[i];
            if (inQuotes)
            {
                if (c == '"' && i + 1 < line.Length && line[i + 1] == '"') { sb.Append('"'); i++; }
                else if (c == '"') inQuotes = false;
                else sb.Append(c);
            }
            else if (c == '"') inQuotes = true;
            else if (c == ',') { fields.Add(sb.ToString()); sb.Clear(); }
            else sb.Append(c);
        }
        fields.Add(sb.ToString());
        return fields;
    }
}
